<?php foreach(['voice_example'=>'Battuta di riferimento per la voce','duty'=>'Dovere e ruolo','goals'=>'Obiettivi personali','honor_code'=>'Codice morale e carattere','boundaries'=>'Limiti e comportamento','narrative_rules'=>'Direttive narrative personalizzate','scene_context'=>'Contesto attuale comune a tutte le conversazioni','allegiance'=>'Comunità servita'] as $key=>$label): ?><label><?=$label?><textarea name="<?=$key?>" rows="3" maxlength="<?=$key==='narrative_rules'?1600:($key==='scene_context'?1200:($key==='voice_example'?450:($key==='allegiance'?80:($key==='duty'?400:($key==='goals'?600:500)))))?>"><?=$h($rules[$key])?></textarea></label><?php endforeach; ?>
<label>Atteggiamento verso l’autorità<select name="authority_attitude"><?php foreach(['contextual'=>'Dal carattere, dai tratti e dal rapporto','loyal'=>'Leale alle istituzioni','skeptical'=>'Critico e diffidente','defiant'=>'Eversivo o contrario all’autorità'] as $k=>$label): ?><option value="<?=$k?>"<?=$rules['authority_attitude']===$k?' selected':''?>><?=$label?></option><?php endforeach; ?></select><small>Conoscere la carica non impone riverenza. Il PNG può rispettare, discutere o contestare secondo la propria indole; paura, fiducia e torti vissuti restano rilevanti.</small></label>
